static CityClothShopBuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityClothShop.request"))return;var mode=File.ReadAllText("CityClothShop.request").Trim();File.Delete("CityClothShop.request");try{if(mode=="build")Build();else if(mode=="refine")Refine();else if(mode=="verify")Verify();else Audit();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/ClothShop.txt",e.ToString());Debug.LogException(e);}}
