static void Audit(){var sc=SceneManager.GetActiveScene();var t=Target(sc);var mesh=t.GetComponent<MeshFilter>().sharedMesh;var vs=mesh.vertices;var ids=mesh.triangles;var b=new StringBuilder("Bounds="+mesh.bounds+"\n");foreach(var axis in new[]{Vector3.forward,Vector3.back,Vector3.left,Vector3.right}){float ymax=0,edge=axis.z>0?mesh.bounds.max.z:axis.z<0?-mesh.bounds.min.z:axis.x>0?mesh.bounds.max.x:-mesh.bounds.min.x;for(int i=0;i<ids.Length;i+=3){var a=vs[ids[i]];var c=vs[ids[i+1]];var d=vs[ids[i+2]];if(Vector3.Dot(Vector3.Cross(c-a,d-a).normalized,axis)>.8f&&new[]{a,c,d}.All(p=>Vector3.Dot(p,axis)>edge-1))ymax=Mathf.Max(ymax,a.y,c.y,d.y);}b.AppendLine("Outer wall "+axis+" maxY="+ymax);}File.WriteAllText("FinalEnvironmentRoadReview/ClothShop.txt",b.ToString());}
static Mesh Reskin(Mesh source,string name){var v=source.vertices;var ids=source.triangles;var ns=source.normals;var p=new List<Vector3>();var uv=new List<Vector2>();var normals=new List<Vector3>();var ti=new List<int>();var bound=source.bounds;for(int k=0;k<ids.Length;k+=3){var a=v[ids[k]];var b=v[ids[k+1]];var c=v[ids[k+2]];var normal=Vector3.Cross(b-a,c-a).normalized;bool front=normal.z>.5f,side=normal.x<-.5f;bool painted=(front||side)&&new[]{a,b,c}.All(q=>q.y<=10.321f);foreach(int j in new[]{ids[k],ids[k+1],ids[k+2]}){var q=v[j];p.Add(q);normals.Add(ns.Length==v.Length?ns[j]:normal);float u=front?Mathf.InverseLerp(bound.max.x,bound.min.x,q.x):Mathf.InverseLerp(bound.max.z,bound.min.z,q.z);uv.Add(painted?new Vector2(64+u,Mathf.Clamp01(q.y/10.321f)):new Vector2(32.15f,Mathf.Clamp01(q.y/13)));ti.Add(ti.Count);}}
var result=new Mesh{name=name,indexFormat=p.Count>65535?UnityEngine.Rendering.IndexFormat.UInt32:UnityEngine.Rendering.IndexFormat.UInt16};result.SetVertices(p);result.SetNormals(normals);result.SetUVs(0,uv);result.SetTriangles(ti,0);result.RecalculateTangents();result.RecalculateBounds();if(result.triangles.Length!=source.triangles.Length||result.bounds!=source.bounds)throw new Exception("Original geometry/bounds mismatch");return result;}
static void Paste(Texture2D to,Texture2D from,RectInt r,int pad){for(int y=-pad;y<r.height+pad;y++)for(int x=-pad;x<r.width+pad;x++){float u=Mathf.Clamp01((x+.5f)/r.width),v=Mathf.Clamp01((y+.5f)/r.height);to.SetPixel(r.x+x,r.y+y,from.GetPixelBilinear(u,v));}}
static void Build(){var sc=SceneManager.GetActiveScene();var t=Target(sc);var mfs=t.GetComponentsInChildren<MeshFilter>(true);if(mfs.Any(m=>m.sharedMesh&&m.sharedMesh.name.StartsWith("Cloth Shop")))throw new Exception("Already built; refusing a duplicate atlas expansion");Directory.CreateDirectory(Backup);EditorSceneManager.SaveScene(sc,Backup+"/Scene.unity",true);var material=AssetDatabase.LoadAssetAtPath<Material>(Mat);if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Shared shader has errors before build");var hospitalUsers=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.sharedMaterials.Contains(material)).ToArray();var userMeshes=hospitalUsers.Select(r=>r.GetComponent<MeshFilter>()?.sharedMesh).ToArray();var userUVs=userMeshes.Select(m=>m?m.uv:null).ToArray();var originalGuid=AssetDatabase.AssetPathToGUID(Atlas);var old=new Texture2D(2,2,TextureFormat.RGB24,false);old.LoadImage(File.ReadAllBytes(Backup+"/City Hospital Facade Atlas.png"));if(old.width!=2172||old.height!=724)throw new Exception("Unexpected hospital source dimensions");var art=new Texture2D(2,2,TextureFormat.RGB24,false);art.LoadImage(File.ReadAllBytes("FinalEnvironmentRoadReview/ClothShop-Facade-Source.png"));var packed=new Texture2D(4096,2048,TextureFormat.RGB24,false);var colors=new Color32[4096*2048];for(int i=0;i<colors.Length;i++)colors[i]=new Color32(28,32,40,255);packed.SetPixels32(colors);var hr=new RectInt(16,1308,2172,724);var cr=new RectInt(2256,1232,1800,800);Paste(packed,old,hr,8); // Then restore source pixels exactly, with no resampling.
packed.SetPixels32(hr.x,hr.y,hr.width,hr.height,old.GetPixels32());Paste(packed,art,cr,8);packed.Apply();var sourcePixels=old.GetPixels32();var hospitalPixels=packed.GetPixels32();for(int i=0;i<sourcePixels.Length;i++)if(!sourcePixels[i].Equals(hospitalPixels[(hr.y+i/hr.width)*4096+hr.x+i%hr.width]))throw new Exception("Hospital source pixels changed");File.WriteAllBytes(Atlas,packed.EncodeToPNG());UnityEngine.Object.DestroyImmediate(old);UnityEngine.Object.DestroyImmediate(art);UnityEngine.Object.DestroyImmediate(packed);AssetDatabase.ImportAsset(Atlas,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(Atlas);importer.maxTextureSize=4096;importer.mipmapEnabled=true;importer.streamingMipmaps=true;importer.isReadable=false;foreach(string platform in new[]{"Android","iPhone"}){var setting=importer.GetPlatformTextureSettings(platform);setting.overridden=true;setting.maxTextureSize=4096;setting.format=TextureImporterFormat.ASTC_6x6;setting.compressionQuality=80;importer.SetPlatformTextureSettings(setting);}var desktop=importer.GetPlatformTextureSettings("Standalone");desktop.maxTextureSize=4096;importer.SetPlatformTextureSettings(desktop);importer.SaveAndReimport();material.SetVector("_CityHospitalAtlasRect",new Vector4(hr.width/4096f,hr.height/2048f,hr.x/4096f,hr.y/2048f));material.SetVector("_CityClothAtlasRect",new Vector4(cr.width/4096f,cr.height/2048f,cr.x/4096f,cr.y/2048f));EditorUtility.SetDirty(material);if(AssetDatabase.AssetPathToGUID(Atlas)!=originalGuid)throw new Exception("Atlas identity changed");
Directory.CreateDirectory(Dir);AssetDatabase.Refresh();var meshes=new Dictionary<Mesh,Mesh>();int before=0,after=0;foreach(var f in mfs){if(!f.sharedMesh)continue;var original=f.sharedMesh;before+=original.triangles.Length/3;if(!meshes.TryGetValue(original,out var updated)){updated=Reskin(original,"Cloth Shop texture only "+meshes.Count);AssetDatabase.CreateAsset(updated,Dir+"/"+updated.name+".asset");meshes.Add(original,updated);}f.sharedMesh=updated;f.GetComponent<Renderer>().sharedMaterial=material;PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<Renderer>());after+=updated.triangles.Length/3;}
for(int i=0;i<hospitalUsers.Length;i++){var f=hospitalUsers[i].GetComponent<MeshFilter>();if(f&&f.sharedMesh!=userMeshes[i])throw new Exception("Hospital mesh reference changed");if(f&&!f.sharedMesh.uv.SequenceEqual(userUVs[i]))throw new Exception("Hospital UV changed");}
if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Shared shader compilation failed");var control=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=control&&control.IsNight;try{if(control)control.Apply(false);Capture(sc,t.TransformPoint(new Vector3(-31,12,33)),t.TransformPoint(new Vector3(-.25f,4.8f,-1.14f)),"ClothShop-Day");Capture(sc,t.TransformPoint(new Vector3(-.25f,5.5f,39)),t.TransformPoint(new Vector3(-.25f,4.8f,12)),"ClothShop-Front");if(control)control.Apply(true);Capture(sc,t.TransformPoint(new Vector3(-31,12,33)),t.TransformPoint(new Vector3(-.25f,4.8f,-1.14f)),"ClothShop-Night");}finally{if(control)control.Apply(night);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/ClothShop.txt","SUCCESS: Texture-only cloth shop on wwww. Original mesh positions/bounds/triangle count retained; LOD renderer count="+mfs.Length+"; summed LOD triangles before="+before+" after="+after+". Existing City Hospital Mobile material reused. Same atlas GUID; original hospital 2172x724 pixels verified identical; "+hospitalUsers.Length+" hospital renderers retain mesh/UV references. Shared atlas now4096x2048, mip streaming, ASTC6x6 Android/iOS; no added material/texture/detail meshes/lights. Weapon shop reserve: bottom left pixel rectangle x16 y16 width1800 height800. Shader errors=0.\nAtlas="+Atlas+"\nMaterial="+Mat);}
static void Refine(){var sc=SceneManager.GetActiveScene();var t=Target(sc);var log=new StringBuilder();foreach(var cc in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CharacterController>(true)))log.AppendLine("Player controller "+cc.name+" height="+cc.height*cc.transform.lossyScale.y);foreach(var rr in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<SkinnedMeshRenderer>(true)).Where(r=>r.bounds.size.y>1&&r.bounds.size.y<3).Take(8))log.AppendLine("Character "+rr.name+" world height="+rr.bounds.size.y);foreach(var f in t.GetComponentsInChildren<MeshFilter>(true)){var source=f.sharedMesh;var v=source.vertices;var ns=source.normals;var ids=source.triangles;var bounds=source.bounds;var p=new List<Vector3>();var uv=new List<Vector2>();var normals=new List<Vector3>();var ti=new List<int>();
for(int k=0;k<ids.Length;k+=3){var corners=new[]{v[ids[k]],v[ids[k+1]],v[ids[k+2]]};bool facade=corners.All(q=>q.z>12.3f&&q.y<10.33f)||corners.All(q=>q.x< -13.7f&&q.y<10.33f);if(facade)continue;foreach(int j in new[]{ids[k],ids[k+1],ids[k+2]}){p.Add(v[j]);normals.Add(ns[j]);uv.Add(new Vector2(32.15f,Mathf.Clamp01(v[j].y/13)));ti.Add(ti.Count);}}
Action<Vector3,Vector3,Vector3,Vector3,Vector2,Vector2,Vector2,Vector2> quad=(a,b,c,d,ua,ub,uc,ud)=>{int n=p.Count;p.AddRange(new[]{a,b,c,d});uv.AddRange(new[]{ua,ub,uc,ud});var normal=Vector3.Cross(b-a,c-a).normalized;normals.AddRange(new[]{normal,normal,normal,normal});ti.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});};
foreach(bool front in new[]{true,false}){float width=front?bounds.size.x:bounds.size.z;Func<float,float,Vector3> point=(x,y)=>front?new Vector3(bounds.max.x-x,y,bounds.max.z+.005f):new Vector3(bounds.min.x-.005f,y,bounds.max.z-x);Action<float,float,float,float,Rect,bool> tile=(x0,x1,y0,y1,r,cloth)=>{float flag=cloth?64:0;quad(point(x0,y0),point(x0,y1),point(x1,y1),point(x1,y0),new Vector2(flag+r.xMin,r.yMin),new Vector2(flag+r.xMin,r.yMax),new Vector2(flag+r.xMax,r.yMax),new Vector2(flag+r.xMax,r.yMin));};
// A normal human entrance: center module 8.8m, 3.05m display glazing, door about2.4m high.
float middle=8.8f,left=(width-middle)*.5f,right=left+middle;tile(left,right,0,3.05f,new Rect(0,0,1,.70f),true);for(int side=0;side<2;side++){float start=side==0?0:right,end=side==0?left:width;int count=Mathf.CeilToInt((end-start)/3.5f);for(int j=0;j<count;j++)tile(Mathf.Lerp(start,end,j/(float)count),Mathf.Lerp(start,end,(j+1f)/count),0,3.05f,new Rect(side==0?0:.67f,0,.33f,.70f),true);}tile(left,right,3.05f,4.24f,new Rect(0,.71f,1,.29f),true);foreach(var span in new[]{new Vector2(0,left),new Vector2(right,width)})tile(span.x,span.y,3.05f,4.24f,new Rect(.15f,.87f,.001f,.001f),true);
// Existing hospital upper glass, without signage, retains the building's original height.
tile(0,width,4.24f,10.32065f,new Rect(.15f,.710f,.70f,.28f),false);}
source.Clear();source.indexFormat=p.Count>65535?UnityEngine.Rendering.IndexFormat.UInt32:UnityEngine.Rendering.IndexFormat.UInt16;source.SetVertices(p);source.SetNormals(normals);source.SetUVs(0,uv);source.SetTriangles(ti,0);source.RecalculateTangents();source.RecalculateBounds();EditorUtility.SetDirty(source);log.AppendLine(f.name+" triangles="+ti.Count/3);}
var control=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=control&&control.IsNight;try{if(control)control.Apply(false);Capture(sc,t.TransformPoint(new Vector3(-31,12,33)),t.TransformPoint(new Vector3(-.25f,4.8f,-1.14f)),"ClothShop-Day");Capture(sc,t.TransformPoint(new Vector3(-.25f,5.5f,39)),t.TransformPoint(new Vector3(-.25f,4.8f,12)),"ClothShop-Front");if(control)control.Apply(true);Capture(sc,t.TransformPoint(new Vector3(-31,12,33)),t.TransformPoint(new Vector3(-.25f,4.8f,-1.14f)),"ClothShop-Night");}finally{if(control)control.Apply(night);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.AppendAllText("FinalEnvironmentRoadReview/ClothShop.txt","\nREFINED: continuous texture facade panels replace old protruding front/side relief within the same two mesh assets; no added renderer or material. Storefront4.24m, display glazing3.05m, central display8.8m, estimated door2.4m. Upper floors retain original building height.\n"+log);}static void Verify(){var sc=SceneManager.GetActiveScene();var t=Target(sc);var material=AssetDatabase.LoadAssetAtPath<Material>(Mat);var original=new Texture2D(2,2,TextureFormat.RGB24,false);original.LoadImage(File.ReadAllBytes(Backup+"/City Hospital Facade Atlas.png"));var expanded=new Texture2D(2,2,TextureFormat.RGB24,false);expanded.LoadImage(File.ReadAllBytes(Atlas));var a=original.GetPixels32();var b=expanded.GetPixels32();int changed=0;for(int i=0;i<a.Length;i++)if(!a[i].Equals(b[(1308+i/2172)*4096+16+i%2172]))changed++;if(changed!=0)throw new Exception("Hospital pixel verification failed");var beforeTexture=material.GetTexture("_BaseMap");var rect=material.GetVector("_CityHospitalAtlasRect");var hospital=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(t)&&r.sharedMaterial==material&&r.bounds.size.z>50).FirstOrDefault();var control=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=control&&control.IsNight;GameObject player=null;try{if(control)control.Apply(false);player=GameObject.CreatePrimitive(PrimitiveType.Capsule);player.name="Temporary 1.8m player scale reference";player.hideFlags=HideFlags.HideAndDontSave;player.transform.SetParent(t,false);player.transform.localPosition=new Vector3(2,.9f,14.6f);player.transform.localScale=new Vector3(.55f,.9f,.55f);Capture(sc,t.TransformPoint(new Vector3(-.25f,3.4f,23)),t.TransformPoint(new Vector3(-.25f,2.1f,13.6f)),"ClothShop-PlayerScale");UnityEngine.Object.DestroyImmediate(player);player=null;if(hospital){var center=hospital.bounds.center;var camera=center+Vector3.right*95+Vector3.up*16;Capture(sc,camera,center,"ClothShop-Hospital-After");material.SetTexture("_BaseMap",original);material.SetVector("_CityHospitalAtlasRect",new Vector4(1,1,0,0));Capture(sc,camera,center,"ClothShop-Hospital-Before");}}finally{if(player)UnityEngine.Object.DestroyImmediate(player);material.SetTexture("_BaseMap",beforeTexture);material.SetVector("_CityHospitalAtlasRect",rect);if(control)control.Apply(night);UnityEngine.Object.DestroyImmediate(original);UnityEngine.Object.DestroyImmediate(expanded);}int near=t.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3;var lod=t.GetComponent<LODGroup>();if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Shader errors");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/ClothShop.txt","SUCCESS: wwww texture-based cloth shop completed. Original footprint/overall height retained; continuous flat front and side replace original arch relief within existing mesh assets. Near triangles="+near+"; LODs="+(lod?lod.lodCount:0)+". Same City Hospital Mobile material and atlas GUID; no added material/texture assets, extra renderers, detail meshes or lights. Existing hospital image2172x724 preserved pixel-for-pixel; persisted hospital pixel differences="+changed+". Hospital mesh/UVs untouched. Same atlas expanded4096x2048 with ASTC6x6 Android/iOS and mip streaming, reserved bottom-left1800x800 for future weapon shop. Scene player controller measured1.8m; temporary player-scale preview removed before saving; glazed store height3.05m; entrance approximately2.5m. Shader errors=0.\nAtlas="+Atlas+"\nMaterial="+Mat+"\nArtwork prompt (built-in image_gen): Orthographic CLOTH SHOP facade, blue/white/navy sign and shirt icon, warm display windows with mannequins and clothing racks, all detail baked into flat texture; no background, plants or added 3D details.\nSource artwork=FinalEnvironmentRoadReview/ClothShop-Facade-Source.png");}}
